import{_ as t,C as s,o as a,c as n,a2 as i,b as l,w as o,a as c,E as d,a3 as u}from"./chunks/framework.CgxQ0r6v.js";const E=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 1","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_IV/documentacion/IV-X/Lectura_Catedra_Evaluacion_1.md","filePath":"materias/Proyecto_Sociotecnologico_IV/documentacion/IV-X/Lectura_Catedra_Evaluacion_1.md"}'),g={name:"materias/Proyecto_Sociotecnologico_IV/documentacion/IV-X/Lectura_Catedra_Evaluacion_1.md"};function m(f,e,p,h,A,I){const r=s("Mermaid");return a(),n("div",null,[e[1]||(e[1]=i('<h1 id="manual-de-estudio-profundo-evaluacion-1" tabindex="-1">Manual de Estudio Profundo: Evaluación 1 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-1" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 1&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-iv-trayecto-iv-trimestre-x" tabindex="-1">Materia: Proyecto Sociotecnológico IV (Trayecto IV - Trimestre X) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-iv-trayecto-iv-trimestre-x" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico IV (Trayecto IV - Trimestre X)&quot;">​</a></h2><h3 id="eje-tematico-diagnostico-estrategico-y-articulacion-integral-hardware-software" tabindex="-1">Eje Temático: Diagnóstico Estratégico y Articulación Integral Hardware/Software <a class="header-anchor" href="#eje-tematico-diagnostico-estrategico-y-articulacion-integral-hardware-software" aria-label="Permalink to &quot;Eje Temático: Diagnóstico Estratégico y Articulación Integral Hardware/Software&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-cuspide-de-la-ingenieria-en-informatica" tabindex="-1">🧭 Introducción: La Cúspide de la Ingeniería en Informática <a class="header-anchor" href="#🧭-introduccion-la-cuspide-de-la-ingenieria-en-informatica" aria-label="Permalink to &quot;🧭 Introducción: La Cúspide de la Ingeniería en Informática&quot;">​</a></h2><p>El <strong>Proyecto Sociotecnológico IV (PST IV)</strong> es el Trabajo Especial de Grado que conduce a la obtención del título de <strong>Ingeniero/a en Informática</strong> de la Universidad Politécnica Territorial del Estado Trujillo &quot;Mario Briceño Iragorry&quot;.</p><p>A este nivel, los proyectos no se limitan al desarrollo aislado de software aplicativo. La ingeniería en informática exige <strong>soluciones integrales</strong>, donde el software interactúa estrechamente con:</p><ul><li>La infraestructura de hardware y servidores físicos o virtualizados.</li><li>Las redes de telecomunicaciones, cableado estructurado o enlaces inalámbricos.</li><li>Dispositivos de automatización, Internet de las Cosas (IoT), sensores, controladores lógicos programables (PLC) o biométricos (si el proyecto lo requiere).</li><li>Las políticas estratégicas de seguridad de la información y soberanía tecnológica del Estado venezolano.</li></ul>',8)),(a(),l(u,null,{default:o(()=>[d(r,{id:"mermaid-41",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20ENG%5B%22%F0%9F%8E%93%20Perfil%20de%20Ingenier%C3%ADa%20Inform%C3%A1tica%20en%20PST%20IV%22%5D%0A%20%20%20%20ENG%20--%3E%20S%5B%22%F0%9F%92%BB%20Ingenier%C3%ADa%20de%20Software%20(Arquitecturas%20avanzadas%2C%20APIs%2C%20Microservicios)%22%5D%0A%20%20%20%20ENG%20--%3E%20H%5B%22%F0%9F%94%8C%20Infraestructura%20y%20Hardware%20(Servidores%2C%20Redes%2C%20Sensores%2C%20IoT)%22%5D%0A%20%20%20%20ENG%20--%3E%20Q%5B%22%F0%9F%93%8A%20Gesti%C3%B3n%20de%20la%20Calidad%20(ISO%2FIEC%2025010%2C%20Auditor%C3%ADa%2C%20M%C3%A9tricas)%22%5D%0A%20%20%20%20ENG%20--%3E%20G%5B%22%F0%9F%8F%9B%EF%B8%8F%20Gesti%C3%B3n%20Estrat%C3%A9gica%20(Soberan%C3%ADa%2C%20Marco%20Legal%2C%20Impacto%20Social)%22%5D%0A%0A%20%20%20%20style%20ENG%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20S%20fill%3A%230369a1%2Cstroke%3A%230ea5e9%2Ccolor%3A%23fff%0A%20%20%20%20style%20H%20fill%3A%230f766e%2Cstroke%3A%2314b8a6%2Ccolor%3A%23fff%0A%20%20%20%20style%20Q%20fill%3A%237c2d12%2Cstroke%3A%23ea580c%2Ccolor%3A%23fff%0A%20%20%20%20style%20G%20fill%3A%234338ca%2Cstroke%3A%236366f1%2Ccolor%3A%23fff%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<hr><h2 id="🏛️-capitulo-i-abordaje-a-organizaciones-estrategicas-y-diagnostico-de-alto-nivel" tabindex="-1">🏛️ CAPÍTULO I: Abordaje a Organizaciones Estratégicas y Diagnóstico de Alto Nivel <a class="header-anchor" href="#🏛️-capitulo-i-abordaje-a-organizaciones-estrategicas-y-diagnostico-de-alto-nivel" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: Abordaje a Organizaciones Estratégicas y Diagnóstico de Alto Nivel&quot;">​</a></h2><p>Los proyectos de PST IV se insertan en instituciones y sectores de relevancia nacional o regional:</p><ol><li><strong>Centros Hospitalarios y Redes de Salud Pública:</strong> Automatización de historias médicas, control epidemiológico y trazabilidad de insumos.</li><li><strong>Empresas del Estado y Complejos Socioproductivos:</strong> Automatización de líneas de producción, gestión de mantenimiento de maquinaria y telemetría.</li><li><strong>Instituciones Educativas y de Investigación:</strong> Plataformas distribuidas de educación abierta y laboratorios remotos.</li><li><strong>Organismos de Seguridad Ciudadana y Protección Civil:</strong> Sistemas de monitoreo de riesgos hidrometeorológicos y alertas tempranas.</li></ol><hr><h2 id="🔬-capitulo-ii-articulacion-por-areas-de-saberes-hardware-y-software" tabindex="-1">🔬 CAPÍTULO II: Articulación por Áreas de Saberes: Hardware y Software <a class="header-anchor" href="#🔬-capitulo-ii-articulacion-por-areas-de-saberes-hardware-y-software" aria-label="Permalink to &quot;🔬 CAPÍTULO II: Articulación por Áreas de Saberes: Hardware y Software&quot;">​</a></h2><p>El diagnóstico debe desglosar la realidad técnica en dos dimensiones convergentes:</p><h3 id="_2-1-dimension-de-hardware-e-infraestructura-fisica" tabindex="-1">2.1 Dimensión de Hardware e Infraestructura Física <a class="header-anchor" href="#_2-1-dimension-de-hardware-e-infraestructura-fisica" aria-label="Permalink to &quot;2.1 Dimensión de Hardware e Infraestructura Física&quot;">​</a></h3><ul><li>Diagnóstico del equipamiento actual: estado de la red eléctrica, sistemas de alimentación ininterrumpida (UPS), puesta a tierra en salas de servidores.</li><li>Topología de red existente: switches capa 2/3, routers, servidores de rack, cableado UTP Cat 6/6A o fibra óptica.</li><li>Diagnóstico de requerimientos de hardware especializado: cámaras de seguridad, lectores de tarjetas RFID, sensores de temperatura o placas controladoras libres (Arduino, Raspberry Pi, ESP32).</li></ul><h3 id="_2-2-dimension-de-software-y-gestion-de-datos" tabindex="-1">2.2 Dimensión de Software y Gestión de Datos <a class="header-anchor" href="#_2-2-dimension-de-software-y-gestion-de-datos" aria-label="Permalink to &quot;2.2 Dimensión de Software y Gestión de Datos&quot;">​</a></h3><ul><li>Análisis de la dispersión de información: bases de datos aisladas, hojas de cálculo incompatibles y duplicidad de registros.</li><li>Cuantificación rigurosa de flujos de datos: tasas de entrada/salida (<em>I/O</em>), tamaño estimado de base de datos en 5 años y requisitos de concurrencia.</li><li>Diagnóstico de vulnerabilidades actuales: uso de sistemas operativos sin soporte, falta de cortafuegos y ausencia de políticas de contraseñas.</li></ul><hr><h2 id="📋-capitulo-iii-especificacion-de-requerimientos-de-nivel-ingenieria-ers" tabindex="-1">📋 CAPÍTULO III: Especificación de Requerimientos de Nivel Ingeniería (ERS) <a class="header-anchor" href="#📋-capitulo-iii-especificacion-de-requerimientos-de-nivel-ingenieria-ers" aria-label="Permalink to &quot;📋 CAPÍTULO III: Especificación de Requerimientos de Nivel Ingeniería (ERS)&quot;">​</a></h2><p>En PST IV, la Especificación de Requerimientos sigue los lineamientos más exigentes del estándar <strong>IEEE 830 / ISO/IEC/IEEE 29148</strong>:</p><ul><li><strong>Requisitos de Interoperabilidad:</strong> Capacidad del nuevo sistema de comunicarse con sistemas existentes mediante APIs seguras.</li><li><strong>Requisitos de Escalabilidad:</strong> Arquitectura modular capaz de crecer horizontal y verticalmente sin rediseño del código.</li><li><strong>Requisitos de Disponibilidad:</strong> Acuerdos de nivel de servicio proyectados (99.5% de tiempo en línea).</li></ul><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-1" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 1 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-1" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 1&quot;">​</a></h2><p>Para la Evaluación 1 del Trimestre X, los aspirantes a ingenieros consignarán:</p><ol><li><strong>Carta de Postulación y Aceptación Formal:</strong> Avalada por la directiva de la organización estratégica.</li><li><strong>Informe de Diagnóstico Estratégico:</strong> Con análisis conjunto de la infraestructura de hardware, redes y necesidades de software.</li><li><strong>Catálogo de Requerimientos ERS de Nivel Ingeniería:</strong> Cubriendo requisitos funcionales, no funcionales y de arquitectura física.</li></ol>',19))])}const b=t(g,[["render",m]]);export{E as __pageData,b as default};
